INCLUDE "CVGLIB.H"


           ORG     $0000

;******************************************************************************************
; CPU Reset Entry Point ($0000–$0005)
; Bypasses the RST $08 vector block and transfers control to cold start.
;******************************************************************************************

L0000:      NOP                             ; Wait for hardware to settle down
            NOP                             ;
            DI                              ; Disable interrupts
L0003:      JP      L0027                   ; Jump to cold start routine

            DB      $31, $00                ; Padding bytes preceding RST $08 vector

;******************************************************************************************
; ----> ENTER (RST $08 Handler) ($0008–$0014)
; TERSE Forth engine entry point. Saves current TERSE IP (BC) onto the Return Stack (IX),
; pops the new TERSE IP from the Parameter Stack, and dispatches via _NEXT.
;******************************************************************************************

_ENTER      EQU     $CF                     ; Z80 opcode for RST $08

            DEC     IX                      ; Push B onto TERSE Return Stack (IX)
            LD      (IX+$00), B             ;
            DEC     IX                      ; Push C onto TERSE Return Stack (IX)
            LD      (IX+$00), C             ;
            POP     BC                      ; Pop new TERSE Interpreter Pointer into BC
            DW      _NEXT                   ; Dispatch next TERSE word

;******************************************************************************************
; Unused Restart Vectors ($0015–$0017)
;******************************************************************************************

            RST     $38                     ; Unused filler vector ($FF)
            RST     $38                     ; Unused filler vector ($FF)
            RST     $38                     ; Unused filler vector ($FF)

;******************************************************************************************
; ----> B@ (RST $18 Handler) ($0018–$001E)
; TERSE Forth Byte-Fetch: Pops address off Parameter Stack, fetches 8-bit byte,
; zero-extends to 16 bits, pushes result back onto stack, and dispatches.
;******************************************************************************************

            POP     HL                      ; Pop target memory address into HL
            LD      E, (HL)                 ; Read byte at (HL) into low byte E
            LD      D, $00                  ; Zero-extend high byte D
            PUSH    DE                      ; Push 16-bit result onto stack
            DW      _NEXT                   ; Dispatch next TERSE word

            NOP                             ; Padding byte before $0020 vector

;******************************************************************************************
; ----> @ / W@ (RST $20 Handler) ($0020–$0026)
; TERSE Forth Word-Fetch: Pops address off Parameter Stack, fetches 16-bit word,
; pushes word onto stack, and dispatches.
;******************************************************************************************

            POP     HL                      ; Pop target memory address into HL
            LD      E, (HL)                 ; Read low byte
            INC     HL                      ;
            LD      D, (HL)                 ; Read high byte
            PUSH    DE                      ; Push 16-bit word onto stack
            DW      _NEXT                   ; Dispatch next TERSE word

;******************************************************************************************
; Cold Start Entry Point ($0027)
; Targeted by reset jump at $0003
;******************************************************************************************

L0027:      NOP                             ; Cold start entry point

;******************************************************************************************
; Cold Start & Outport Initialization ($0028–$0030)
; RST $28 vector entry point. Clears the first 24 hardware outports ($00–$17).
;******************************************************************************************

L0028:      NOP                             ; Cold start / RST $28 entry point
            XOR     A                       ; Clear accumulator (A = 0)
            LD      C, $18                  ; Set counter for 24 outports ($00–$17)
L002C:      DEC     C                       ; Decrement port index
            OUT     (C), A                  ; Output $00 to port (C)
            JR      NZ, L002C               ; Loop until ports $17 down to $00 are cleared

;******************************************************************************************
; Commercial Mode & Top System RAM Test ($0031–$003E)
;******************************************************************************************

            INC     A                       ; A = 1
            OUT     (CONCM), A              ; Enable Commercial Mode (Port $08)

            LD      HL, $FEFF               ; Point to RAM test address ($FEFF)
L0037:      LD      (HL), A                 ; Test write to RAM location
            CP      (HL)                    ; Verify write succeeded
            JR      NZ, L0037               ; Loop if write/read fails

            LD      (HL), $00               ; Clear test RAM location
            LD      B, $00                  ; Initialize 256-pass counter

;******************************************************************************************
; RAM Clear Loop Setup ($003F–$0047)
;******************************************************************************************

L003F:      LD      IX, $FF80               ; Set IX register pointer
            LD      SP, $0000               ; Set Stack Pointer
            DJNZ    L003F                   ; Loop 256 times

;******************************************************************************************
; Turn Off Special Control Input $15 Latches ($0048–$0053)
; Clears "Special" CONTROL Input $15 Latches 0 through 7
;******************************************************************************************

            LD      A, $08                  ; Set loop counter for 8 latches
            LD      BC, $0015               ; Point B = 0, C = Port $15 (SW5)
L004D:      IN      L, (C)                  ; Read input port
            INC     B                       ; Advance latch index
            INC     B                       ;
            DEC     A                       ; Decrement loop counter
            JR      NZ, L004D               ; Loop until all 8 latches processed

;******************************************************************************************
; Service Switch Verification ($0054–$005C)
;******************************************************************************************

            IN      A, (SW0)                ; Read Control Port SW0
            BIT     SERVICE, A              ; Test Service Mode bit (active low)
            JR      Z, L006B                ; If Service switch is ON, jump to test mode
            JP      L00A2                   ; Else jump to normal game setup

;******************************************************************************************
; If bad checksum for X1 ROM Strobe white stripes and lock game
;******************************************************************************************

L005D:  LD      A,$07
L005F:  LD      C,$00
L0061:  OUT     (C),A
        OUT     (C),C
        JR      L0061

;******************************************************************************************
; If a bad Write/Read of Static RAM x24 Strobe dark red stripes
;******************************************************************************************

L0067:  LD      A,$53
        JR      L005F

;******************************************************************************************
; We are in Service mode. Test ROM X1 -X10 ???
;******************************************************************************************

L006B:  LD      HL,L0000        ; for Bottom of Robby Roto X1 ROM
L006E:  LD      BC,$1000        ; for 4096 bytes
        XOR     A
L0072:  ADD     A,(HL)          ; compute CheckSum byte
        CPI
        JP      PE,L0072        ; JumP if No Overflow of BC down-counting

        INC     A               ; roll $FF over to $00 if Correct Sum

        EX      AF,AF'
        LD      A,H
        SUB     $11             ; is past ROM x10 ?
        JR      C,L0084                 ; (+$05) safely if first pass
        EX      AF,AF'

        POP     BC              ; restore Terse Program Counter (TPC)
        PUSH    AF              ; save CheckSum and Zero Flag
        DW	_NEXT            ; indexed RETurn

L0084:  EX      AF,AF'          ; hopefully Zero Flag was set, else ...
        JR      NZ,L005D                ; (-$2a) to CheckSum error

;******************************************************************************************
; We are in service mode. Test top 1K of Static RAM
;******************************************************************************************

        LD      DE,$0001        ; 1 for ??
        LD      A,$55           ; 01010101B for Test pattern in Color 1
        LD      B,$02

L008E:  LD      HL,$FF00        ; start at 65280 ?? in Static RAM ??

L0091:  LD      (HL),A
        CP      (HL)
        JR      NZ,L0067                ; (-$2e) if Bad Write/Read error
        ADC     HL,DE           ; count up 65280 to 65535 (by 1 in DE)
        JR      NZ,L0091                ; (-$08) until rolled over to 0
        LD      A,$AA           ; 10101010B for Test pattern in Color 2
        DJNZ    L008E                   ; (-$0f) for another pass

        LD      BC,L0E90        ; point to "Service Mode table"
        JR      L00A5                   ; (+$03) made it through Service mode

;******************************************************************************************
; Service switch was OFF entry point
;******************************************************************************************

L00A2:  LD      BC,LDBF0        ; point to Terse Routine to Start ROBBY ROTO

;******************************************************************************************
; Service switch was ON entry point
;******************************************************************************************

L00A5:  LD      IY,L00A9        ; set Indexed RETurn to next instruction

;******************************************************************************************
; Start of TERSE Forth ENGINE code
; Engine comments borrowed from Commander Dave
; aka David E. Turner <dturner1003@gmail.com>
;
; TERSE REGISTER USE: (best I understand it)
; --> 20200509	May not be correct	-Dave
;
; BC = Interpreter Pointer (IP)
; SP = Parmeter Stack Pointer (PSP)
; IX = Return Stack Pointer (RSP)
; IY = Dispatcher - for ASSEMBLED TERSE words
;*****************************************************************************

;******************************************************************************************
; ----> NEXT   Run next Terse Instruction - Dispatcher ???
;******************************************************************************************
_NEXT	EQU	$E9FD           ; Z80 opcode for jp (iy)

L00A9:  LD      A,(BC)          ; RST $08 jumps here
        INC     BC
        LD      L,A
        LD      A,(BC)
        INC     BC
        LD      H,A
        JP      (HL)

;******************************************************************************************
; ----> RETURN  Terse instructions complete - Return
;******************************************************************************************
_RETURN	EQU	$               ; Terse instruction RETURN jumps here

LD      C,(IX+$00)
        INC     IX
        LD      B,(IX+$00)
        INC     IX
        DW	_NEXT

;******************************************************************************************
; ----> LITword   Get next word and push to user stack
;******************************************************************************************
_LITword        EQU	$

LD      A,(BC)
        INC     BC
        LD      L,A
        LD      A,(BC)
        INC     BC
        LD      H,A
        PUSH    HL
        DW	_NEXT

;******************************************************************************************
; ----> LITbyte  Get next byte and push on user stack ($00xx)
;******************************************************************************************
_LITbyte        EQU	$

LD      A,(BC)
        INC     BC
        LD      L,A
        LD      H,$00
        PUSH    HL
        DW	_NEXT



;******************************************************************************************
; ----> ???     Get next IP address and add offset from user stack
;               and push result to user stack.
;
; Notes from original comments:
;       TERSE Forth nameP does "Pop HL, read (BC) word to DE, add HL,DE and Push HL"
;       Sucks 1 Word following TerseCALL and add offset from user stack
;       "TERSE Forth nameP". Could that be the instruction name ???
;******************************************************************************************

POP     HL              ; "restore HL"
L00CE:  LD      A,(BC)          ; "read (BC) word to DE"
        INC     BC
        LD      E,A
        LD      A,(BC)
        INC     BC
        LD      D,A
        ADD     HL,DE           ; "ADD DE to HL"
        PUSH    HL              ; and "store HL"
        DW	_NEXT            ; indexed RETurn


;******************************************************************************************
; ----> ???	Double number from user stack and add offset from
;		user stack and push result to user stack.
;
; Notes from original comments:
; ??? does "Pop HL, times 2, read (BC) word to DE, add HL,DE and Push HL"
; note: Sucks 1 Word following TerseCALL
;******************************************************************************************

POP     HL
        ADD     HL,HL           ; times 2
        JP      L00CE           ; and add offset from user stack

;******************************************************************************************
; ----> 0      Puts a 0 on the stack (0 is a CONSTANT)
;******************************************************************************************

_0	EQU	$
LD      HL,$0000        ; 0 is a CONSTANT
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
; ----> 1      Puts a 1 on the stack (1 is a CONSTANT)
;******************************************************************************************
_1	EQU	$
LD      HL,$0001        ; 1 is a CONSTANT
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
;----> DUP
;******************************************************************************************

_DUP	EQU	$
POP     HL
        PUSH    HL              ; do "Push HL twice"
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
; ----> 2DUP   Duplicate the top two values on the stack
;******************************************************************************************

_2DUP	EQU	$
POP     HL
        POP     DE
        PUSH    DE
        PUSH    HL
        PUSH    DE
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
; ----> DROP
;******************************************************************************************

_DROP	EQU	$
POP     HL
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
; ----> R>	Pop the value from the return stack and push it
;		onto the user stack. ( See >R )
;******************************************************************************************

_Rgt	EQU	$
LD      L,(IX+$00)
        INC     IX
        LD      H,(IX+$00)
        INC     IX
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
; ----> >R	Push m onto top of the return stack. ( See R> )
;******************************************************************************************

_gtR	EQU	$
POP     HL
        DEC     IX
        LD      (IX+$00),H
        DEC     IX
        LD      (IX+$00),L
        DW	_NEXT            ; indexed RETurn

;******************************************************************************************
; ----> SWAP
;******************************************************************************************

_SWAP	EQU	    $0113
        POP     HL
        POP     DE
        PUSH    HL
        PUSH    DE
        DW	_NEXT            ; indexed RETurn

;********************************************************************
; ----> SP@     Put stack address on the stack ???
;********************************************************************
; Note - Not included ???
;
;         ld      hl,$0000
;         add     hl,sp
;         push    hl
;         DW	_NEXT
;

;******************************************************************************************
; ----> @ ???   Get contents of address on stack and push it on stack
;******************************************************************************************

POP     HL
        LD      E,(HL)
        INC     HL
        LD      D,(HL)
        PUSH    DE
        DW	_NEXT            ; indexed RETurn

; TERSE Forth B@ does "Pop HL from System stack, Push 0,(HL) byte to System stack"
; aka "Get lower byte of address on stack and push to stack"
POP     HL
        LD      E,(HL)
        LD      D,$00
        PUSH    DE
        DW	_NEXT            ; indexed RETurn

; TERSE Forth ! does "Pop HL, Pop DE, word DE->(HL)"
; aka "Store m at address p  [e.g.]  (p) <-- m "
POP     HL
        POP     DE
L0129:  LD      (HL),E          ; "DE->(HL)" entry point
        INC     HL
        LD      (HL),D
        DW	_NEXT            ; indexed RETurn

; TERSE Forth B! does "Pop HL, Pop DE, Only byte E->(HL)"
; aka "Store integer i to value at address p  [e.g.] (p) <-- i "
POP     HL
        POP     DE
        LD      (HL),E
        DW	_NEXT            ; indexed RETurn

; TERSE Forth ZERO does "Pop HL, word 00->(HL)"
; aka Set the word at a memory location to zero.
POP     HL
        LD      (HL),$00
        INC     HL
        LD      (HL),$00
        DW	_NEXT            ; indexed RETurn

; TERSE Forth + does "Pop DE, Pop HL, Push HL + DE"
; aka "ADD word (SP) to (SP+2), Push SUM" for "16 bit integer addition  q=m+n "
POP     DE
        POP     HL
        ADD     HL,DE
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth - does "Pop DE, Pop HL, Push HL - DE"
; aka "SUBtract word (SP) from (SP+2), Push DIFFERENCE"
POP     DE
        POP     HL
L0143:  XOR     A
        SBC     HL,DE
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth MINUS does "Pop DE, Push 00 - DE" for TWO's complement Top of System stack
POP     DE
L014A:  LD      HL,$0000
        JP      L0143                   ; not JR ?? to "Push HL - DE"

; TERSE Forth COM would do "Pop DE + 1, Push 00 - DE" for ONE's COMplement Top of System stack ??
; L0150: not used ?? why not just use CPL ??
        POP     DE
        INC     DE
        JP      L014A                   ; not JR ?? to "00->HL, Push HL - DE"

; TERSE Forth 1- does "DECrement Top of System stack"
POP     HL
        DEC     HL
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth 1+ does "INCrement Top of System stack"
POP     HL
        INC     HL
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth 2+ does "ADD 2 to Top of System stack"
POP     HL
        INC     HL
        INC     HL
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; L0165: not used ?? TERSE Forth 2- would do "SUBtract 2 from Top of System stack"
        POP     HL
        DEC     HL
        DEC     HL
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth 2* does "Double Top of System stack"
POP     HL
        ADD     HL,HL           ; times 2
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth 2/MOD does "DIVide by 2 Top of System stack"
POP     HL
        SRA     H
        RR      L
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth ABS does "ABSolute value of Top of System stack"
POP     HL
        BIT     7,H             ; test SIGN bit ?
        JP      P,L0185                 ; skip if Positive
        EX      DE,HL           ; NEGATE if Negative
        LD      HL,$0000
        XOR     A
        SBC     HL,DE
L0185:  PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth ?? does "INC Top of System stack, then make a BYTE ABSolute"
; aka "INCrement Top of System stack, then Push Old MASKed with 127"
; note: NOT the new BABS routine
POP     HL
        LD      A,(HL)
        INC     HL
        PUSH    HL              ; ??
        LD      L,A
        RES     7,L             ; for POSITIVE Byte
        LD      H,$00
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

;********************************************************************
; ----> 1-!        Subtract 1 from the contents of memory location.
;********************************************************************
;         pop     hl
;         dec     (hl)
;         DW	_NEXT
;

;********************************************************************
; ----> 1+!        Add 1 to the contents of memory location.
;********************************************************************
;         pop     hl
;         inc     (hl)
;         DW	_NEXT
;

; TERSE Forth = does "Pop DE, Pop HL, Push T on EQUAL or F on Not Equal"
POP     DE
L0195:  POP     HL              ; entry with DE = 0
        XOR     A
        SBC     HL,DE
        LD      HL,$0000        ; FALSE ??
        JR      NZ,L019F                ; (+$01)
        INC     HL              ; or TRUE ??
L019F:  PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth <> does "Pop DE, Pop HL, T on NOT EQUAL or Push F on Equal"
POP     DE
L01A3:  POP     HL              ; entry with DE = 0
        XOR     A
        SBC     HL,DE
        LD      HL,$0000        ; FALSE ??
        JR      Z,L01AD                 ; (+$01)
        INC     HL              ; or TRUE ??
L01AD:  PUSH    HL
        DW	_NEXT            ; indexed RETurn

; ?? TERSE Forth <= does "Pop DE, Pop HL, Push T for LESS OR EQUAL or F for Greater Than"
POP     DE
        POP     HL
        XOR     A
        SBC     HL,DE
        LD      HL,$0000        ; FALSE ??
        JR      C,L01BB                 ; (+$01)
        INC     HL              ; or TRUE ??
L01BB:  PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth < does "Pop DE, Pop HL, Push T for LESS Than or F for Greater or Equal
; from L03F2 does "TEST (SP) LESS Than (SP+2) return in (SP)"
POP     DE
L01BF:  POP     HL
L01C0:  XOR     A
        SBC     HL,DE
        LD      DE,$0000        ; 0 for False
        PUSH    AF              ; check out Flags
        POP     HL
        LD      A,L
        AND     $84             ; #10000100 mask for Sign and Parity/Overflow
        JP      PE,L01CF
        INC     DE              ; 1 for True
L01CF:  PUSH    DE
        DW	_NEXT            ; indexed RETurn

; ?? TERSE Forth >= does "TEST (SP) Less or Equal (SP+2) return in (SP)" ??
POP     DE
L01D3:  POP     HL
L01D4:  XOR     A
        SBC     HL,DE
        LD      DE,$0000        ; 0 for False
        PUSH    AF              ; check out Flags
        POP     HL
        LD      A,L
        AND     $84             ; #10000100 mask for Sign and Parity/Overflow
        JP      PO,L01E3
        INC     DE              ; 1 for True
L01E3:  PUSH    DE
        DW	_NEXT            ; indexed RETurn

; ?? does"TEST (SP+2) GREATER Than (SP) return in (SP)"
POP     HL
L01E7:  POP     DE
        JP      L01C0                   ; not JR ??

; ?? does "TEST (SP+2) Less or Equal (SP) return in (SP)"
POP     HL
L01EC:  POP     DE
        JP      L01D4                   ; not JR ??

; TERSE Forth 0= does "Pop HL, Push T on ZERO or F on Not Zero"
L01F0:  LD      DE,$0000
        JP      L0195                   ; not JR ??

; TERSE Forth 0<> does "Pop HL, Push F on Zero or T on Not ZERO"
LD      DE,$0000
        JP      L01A3                   ; not JR ??

; ?? TERSE Forth 0< ?? does "TEST (SP) Less Than ZERO return in (SP)"
LD      DE,$0000
        JP      L01BF                   ; not JR ??

; ?? L0202: TERSE Forth 0<> ?? not used ?? does "TEST (SP) Less or Equal ZERO return in (SP)"
        LD      DE,$0000
        JP      L01D3                   ; not JR ??

; ?? does "TEST ZERO Less Than (SP) return in (SP)"
LD      HL,$0000
        JP      L01E7                   ; not JR ??

; ?? does "TEST ZERO Less or Equal (SP) return in (SP)"
LD      HL,$0000
        JP      L01EC                   ; not JR ??

; TERSE Forth NOT does JumP to TERSE Forth 0= "TEST (SP) Equal ZERO return in (SP)"
JP      L01F0                   ; not JR ??

; TERSE Forth -DUP does "DUPlicate Top of System stack IF Not Zero"
POP     HL
        PUSH    HL
        LD      A,L
        OR      H
        JR      Z,L021E                 ; (+$01)
        PUSH    HL
L021E:  DW	_NEXT            ; indexed RETurn

; TERSE Forth AND does "Pop DE, Pop HL, Push HL AND DE word"
POP     DE
        POP     HL
        LD      A,L
        AND     E
        LD      L,A
        LD      A,H
        AND     D
        LD      H,A
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth OR does "Pop DE, Pop HL, Push HL OR DE word"
POP     DE
        POP     HL
        LD      A,L
        OR      E
        LD      L,A
        LD      A,H
        OR      D
        LD      H,A
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth XOR does "Pop DE, Pop HL, Push HL XOR DE word"
POP     DE
        POP     HL
        LD      A,L
        XOR     E
        LD      L,A
        LD      A,H
        XOR     D
        LD      H,A
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth BMOVE does "Copy (SP) BYTES from (SP+4) source to (SP+2)"
; aka "Pop BC, Pop DE, Pop HL, LDIR IF BC Not Zero" OVERLAPPING CAN OCCUR !!
EXX
        POP     BC              ; Byte Count
        POP     DE              ; DEstination
        POP     HL              ; High & Low of source
        LD      A,B
        OR      C
        JR      Z,L024B                 ; (+$02)
        LDIR                    ; Load, Increment, Repeat
L024B:  EXX
        DW	_NEXT            ; indexed RETurn

;********************************************************************
; Terse note: !! start of ASSEMBLED "end start DO ... LOOP" code !!
; see: Z-80 "count DO/LOOP" aka "LD  B,count | label ... DJNZ label"
;********************************************************************
;
; TERSE Forth DO does "TerseDO Loop begin" (SP) = START, (SP+2) = END limit
; Pop HL for START Count, Pop DE for END Value, keep old BC then PUSH All 3 to TERSE Stack
LD      DE,$FFFA        ; -6 for Loop Quantum
        ADD     IX,DE           ; IndeX was old TERSE Stack Pointer
        POP     HL
        POP     DE
        LD      (IX+$00),L      ; store START value to TERSE Stack (also Loop COUNTer !!)
        LD      (IX+$01),H
        LD      (IX+$02),E      ; store END value to TERSE Stack (check for Limit)
        LD      (IX+$03),D
        LD      (IX+$04),C      ; store TOP of LOOP (Program Counter) to TERSE Stack
        LD      (IX+$05),B
        DW	_NEXT            ; indexed RETurn

; TERSE Forth LOOP does "TerseLOOP back to TerseDO or continue" with BC = next location
; note: INCrements COUNTer, checks against END Limit, LOOPs Back if Not OVERflow
LD      L,(IX+$00)      ; Loop COUNTer on TERSE Stack
        LD      H,(IX+$01)
        INC     HL
        LD      (IX+$00),L      ; Loop COUNTer on TERSE Stack again
        LD      (IX+$01),H
        LD      E,(IX+$02)      ; read END Value
        LD      D,(IX+$03)
        XOR     A
        SBC     HL,DE
        PUSH    AF              ; check out Flags
        POP     HL
        LD      A,L
        AND     $84             ; 10000100B mask for Sign and Parity/Overflow
        JP      PO,L028F
        LD      DE,$0006        ; past END Limit, so done with TERSE Stack
        ADD     IX,DE           ; +6 for Loop Quantum
        JP      L0295                   ; not JR ?? and continue after Next

; read back TOP of LOOP TersePC address from TerseSTACK and Keep LOOPing
L028F:  LD      C,(IX+$04)      ; offset +4 for (inner) LOOP on TERSE Stack
        LD      B,(IX+$05)
L0295:  DW	_NEXT            ; indexed RETurn

; TERSE Forth I does "Push TERSE Loop COUNTer onto System Stack"
LD      L,(IX+$00)      ; Loop COUNTer on TERSE Stack
        LD      H,(IX+$01)
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

; TERSE Forth J does "Push Previous TERSE Loop COUNTer onto System Stack"
LD      L,(IX+$06)      ; +6 for 1 Loop Quantum
        LD      H,(IX+$07)
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

