; { BLOCK 0121 }
; ( RANDOM # WITHOUT REPLACEMENT )
; XC? NOT IFTRUE
;  ;S
; IFEND
; HEX
; F= lur
; CODE URND
; <ASSEMBLE
;  H POP,
;  D POP,
;  B PUSH,
;  M A MOV,
;  E CMP,
;  0<>, IF,
;   E M MOV,
;  LABEL lur
;   H PUSH,
;   M C MOV,
;   H INX,
;   0 M MVI,
;   H INX,
;   C A MOV,
;   RRC,
;   RRC,
;   RRC,
;   1F ANI,
;   A B MOV,
;   C A MOV,
;   7 ANI,
;   0<>, IF,
;    B INR,
;   THEN,
;   BEGIN,
;    0 M MVI,
;    H INX,
;   LOOP,
;   H POP,
;  THEN,
;  H INX,
;  M A MOV,
;  H DCX,
;  M CMP,
;  lur JRNC,
;  M E MOV,
;  0 D MVI,
;  H PUSH,
;  rnd CALL,
;  L C MOV, ( C= CAND )
;  H POP, ( HL= TBL )
;  A XRA,
;  EXAF,
; -->
;
; { BLOCK 0141 }
; ( MORE NIFTY RND WITHOUT REPLACEMENT )
;  BEGIN,
;   C A MOV,
;   RRC,
;   RRC,
;   RRC,
;   1F ANI,
;   2 ADI,
;   A E MOV,
;   0 D MVI,
;   C A MOV,
;   7 ANI,
;   BIT^ CALL,
;   A B MOV,
;   H PUSH,
;   D DAD,
;   M A MOV,
;   B ANA,
;  0<>, WHILE,
;   H POP,
;   EXAF,
;   A INR,
;   0=, IF,
;    lur JMPR,
;   THEN,
;   EXAF,
;   C A MOV,
;   A INR,
;   M CMP,
;   0=, IF,
;    A XRA,
;   THEN,
;   A C MOV,
;  REPEAT,
;  M A MOV,
;  B ORA,
;  A M MOV,
;  H POP,
;  H INX,
;  M INR,
;  C L MOV,
;  0 H MVI,
;  B POP,
;  H PUSH,
; NEXT
; ASSEMBLE>
; DECIMAL
; -->
;
; URND does "Unsigned RaNDom # without replacement"
POP     HL
        POP     DE
        PUSH    BC
        LD      A,(HL)
        CP      E
        JR      Z,L83B8                 ; (+$1a) IF 0<> False skip to THEN
        LD      (HL),E
L839F:  PUSH    HL              ; lur loop
        LD      C,(HL)
        INC     HL
        LD      (HL),$00
        INC     HL
        LD      A,C
        RRCA
        RRCA
        RRCA
        AND     $1F
        LD      B,A
        LD      A,C
        AND     $07
        JR      Z,L83B2                 ; (+$01) IF 0<> False skip
        INC     B
L83B2:  LD      (HL),$00        ; BEGIN loop #1 for B times
        INC     HL
        DJNZ    L83B2                   ; (-$05) LOOP to BEGIN #1
        POP     HL
L83B8:  INC     HL              ; THEN
        LD      A,(HL)
        DEC     HL
        CP      (HL)
        JR      NC,L839F                ; (-$1f) if ?? to lur
        LD      E,(HL)
        LD      D,$00
        PUSH    HL
        CALL    L1A4C           ; rnd do "SHIFT and limit RANGE for Next Pseudo-RANDOM Number"
        LD      C,L             ; ( C= CAND )
        POP     HL              ; ( HL= TBL )
        XOR     A
        EX      AF,AF'
; ( MORE NIFTY RND WITHOUT REPLACEMENT )
L83C9:  LD      A,C             ; BEGIN loop #2
        RRCA
        RRCA
        RRCA
        AND     $1F
        ADD     A,$02
        LD      E,A
        LD      D,$00
        LD      A,C
        AND     $07
        CALL    L81BA           ; BIT^ do "Bit in A to Mask Translation"
        LD      B,A
        PUSH    HL
        ADD     HL,DE
        LD      A,(HL)
        AND     B
        JR      Z,L83F2                 ; (+$11) WHILE 0<> False to loop Exit
        POP     HL
        EX      AF,AF'
        INC     A
        JR      NZ,L83E8                ; (+$02) IF 0= False skip
        JR      L839F                   ; (-$49) to lur

; THEN skip ??
L83E8:  EX      AF,AF'
        LD      A,C
        INC     A
        CP      (HL)
        JR      NZ,L83EF                ; (+$01) IF 0= False skip
        XOR     A
L83EF:  LD      C,A
        JR      L83C9                   ; (-$29) REPEAT to BEGIN #2

; (loop Exit does ??)
L83F2:  LD      A,(HL)
        OR      B
        LD      (HL),A
        POP     HL
        INC     HL
        INC     (HL)
        LD      L,C
        LD      H,$00
        POP     BC
        PUSH    HL
        DW	_NEXT            ; indexed RETurn
; end of ( RANDOM # WITHOUT REPLACEMENT ) !!

