        DW      $04ED           ; 2 "BYTE Pusher" for ??
        DW      $041E           ; / do "word (SP) DIVide by (SP+2), Push QUOTIENT, Discard REMAINDER"
        DW      $013B           ; + do "ADD (SP) to (SP+2), Push SUM"
        DW      $00C5           ; do "pushBYTE to System stack"
        DB      $67             ; 103 for ??
        DW      $0141           ; - do "SUBtract word (SP) from (SP+2), Push DIFFERENCE"
        DW      $00B0           ; ... TerseRETurn

