; { BLOCK 0197 }
; ( NODE ZAMMERS )
; ( SUBR node^ D= ROW E= COL C= DISP, OUT HL= ^ )
; SUBR node^
;  D PUSH,
;  D A MOV,
;  RLC,
;  A L MOV,
;  RLC,
;  RLC,
;  L ADD,
;  D ADD,
;  E ADD,
;  A E MOV,
;  0 D MVI,
;  E L MOV,
;  D H MOV,
;  D DAD,
;  D DAD, ( HL= A*3 )
;  XCHG,
;  H DAD,
;  H DAD,
;  H DAD,  ( A*8 )
;  XCHG,
;  D DAD,
;  D DAD,
;  D DAD,
;  C E MOV,
;  0 D MVI,
;  D DAD, ( ADD DISPLACEMENT )
;  0 NODEMAT D LXI,
;  D DAD,
;  D POP,
;  RET,
;
; node^ does "NODE Zammer ( D= ROW E= COL C= DISP, OUT HL= ^ )"
L865E:  PUSH    DE
        LD      A,D
        RLCA                    ; ROW times 2
        LD      L,A
        RLCA
        RLCA                    ; times 8 now
        ADD     A,L             ; ... 10
        ADD     A,D             ; * 11 total
        ADD     A,E             ; plus COLumn
        LD      E,A
        LD      D,$00
        LD      L,E             ; save as Word A for ??
        LD      H,D
        ADD     HL,DE           ; times 2
        ADD     HL,DE           ; ( HL= A*3 )
        EX      DE,HL
        ADD     HL,HL
        ADD     HL,HL
        ADD     HL,HL           ; ( A*8 )
        EX      DE,HL
        ADD     HL,DE           ; ... 11
        ADD     HL,DE           ; ?? 19
        ADD     HL,DE           ; 27 for NODSIZ ??
        LD      E,C
        LD      D,$00
        ADD     HL,DE           ; ( ADD DISPLACEMENT )
        LD      DE,$E792        ; NODEMAT point to "NODE MATrix" NM-S Byte Array in NV RAM
        ADD     HL,DE
        POP     DE
        RET

