        SBC     HL,DE
        LD      A,L
        CALL    L8759           ; SQUARE do ??
        POP     DE
        ADD     HL,DE
        CALL    L85A7           ; sqrt do "new SQuare RooT"
        LD      B,A             ; ( B= DISTance )
