        DB      $0B             ; constant 11 for "Number of COLumnS"
        ;
        DW      $00DD           ; 0 do "Push WORD 0 to System stack"
        ; TerseDO Loop #1 begin (for Pop START Count up to Pop END Value)
        DW      $024E           ; DO loop "(SP) = START, (SP+2) = END limit"
        ;
        DW      $00C5           ; NROWS "pushBYTE to System stack"
        DB      $06             ; constant 6 for "Number of ROWS"
        ;
        DW      $00DD           ; 0 do "Push WORD 0 to System stack"
        ; _TerseDO Loop #2 begin (for Pop START Count up to Pop END Value)
        DW      $024E           ; DO loop "(SP) = START, (SP+2) = END limit"
        ;
        DW      $02A0           ; J do "Push Previous TERSE Loop COUNTer onto System Stack"
        ;
        DW      $0297           ; I do "Push TERSE Loop COUNTer onto System Stack"
        ;
        DW      $00C5           ; NODX "pushBYTE to System stack"
        DB      $00             ; constant 0 for ??
        ;
        DW      $86F4           ; NODE@ do ??
        ;
        DW      $89B5           ; XADJ do "convert Screen +/- X to Bytes offset from Left side"
        ;
        DW      $02A0           ; J do "Push Previous TERSE Loop COUNTer onto System Stack"
        ;
        DW      $0297           ; I do "Push TERSE Loop COUNTer onto System Stack"
        ;
        DW      $00C5           ; NBX "pushBYTE to System stack"
        DB      $04             ; constant 4 for ??
        ;
        DW      $86ED           ; NODE! do ??
        ;
        DW      $02A0           ; J do "Push Previous TERSE Loop COUNTer onto System Stack"
        ;
        DW      $0297           ; I do "Push TERSE Loop COUNTer onto System Stack"
        ;
        DW      $00C5           ; NODY "pushBYTE to System stack"
        DB      $02             ; constant 2 for ??
        ;
        DW      $86F4           ; NODE@ do ??
        ;
        DW      $89BC           ; YADJ do "convert +/- Y to PIXEL lines from the Top of Screen"
        ;
        DW      $02A0           ; J do "Push Previous TERSE Loop COUNTer onto System Stack"
        ;
        DW      $0297           ; I do "Push TERSE Loop COUNTer onto System Stack"
        ;
        DW      $00C5           ; NBY "pushBYTE to System stack"
        DB      $06             ; constant 6 for ??
