        LD      C,A
        AND     $0F
        LD      (HL),A
        INC     HL
        LD      A,C
        RRCA
        RRCA
        RRCA
        RRCA
        AND     $0F
        LD      (HL),A
        INC     HL
        INC     HL
        INC     HL
        INC     HL
        INC     HL
        INC     DE
        DJNZ    L8EC8                   ; (-$16) LOOP to DO #1 for 3
        POP     HL
        LD      DE,$000B        ; 11 for ??
        ADD     HL,DE
        LD      DE,$0000        ; 0 for ??
; ( ADVANCE TO NODE AREA )
        LD      B,$21           ; (NNODES / 2) = 33
L8EE8:  LD      A,(HL)          ; DO loop #2 for NNODES 2/
        RRCA                    ; divide ?? by 8
        RRCA
        RRCA
        RRCA
