        LD      A,(HL)
        CALL    L8E9E           ; MN-L do "Make Node entry" again ??
        INC     HL
        DJNZ    L8EE8                   ; (-$0f) LOOP to DO #2 for 33
        POP     BC
        DW	_NEXT            ; indexed RETurn
; end of ( HOSTAGE HIDER AND MAZE GENERATOR ) !!

