; SUBR XOR-FLIP
;  VOXPAND Y B LDX,
;  VOMAGIC Y C LDX,
;  VOPATH Y H LDX,
;  VOPAT Y L LDX,
;  H INX,
;  H INX, ( pat off set)
;  H PUSH,
;  X POPX,
;  VOSCRADRH Y H LDX,
;  VOSCRADR Y L LDX,
;  writep JMP, ( erase it )
