        LD      C,(IY+$22)      ; VOMAGIC offset 34
        LD      H,(IY+$2B)      ; VOPATH offset 43
        LD      L,(IY+$2A)      ; VOPAT offset 42
        INC     HL
        INC     HL              ; ( pat off set)
        PUSH    HL
        POP     IX              ; restore as Terse SP
        LD      H,(IY+$2F)      ; VOSCRADRH offset 47
        LD      L,(IY+$2E)      ; VOSCRADR offset 46
; then ( erase it )
