; SUBR VIS?
;  H PUSH,
;  B PUSH,
;  Y PUSHX,
;  H POP,
;  VISMAT B LXI,
;  B DAD,
;  E C MOV,
;  0 B MVI,
;  B DAD,
;  D A MOV,
;  BIT^ CALL,
;  M ANA,
;  B POP,
;  H POP,
;  RET,
;
; VIS? does "Route search routine ??" routine
L993B:  PUSH    HL
        PUSH    BC
        PUSH    IY
        POP     HL
        LD      BC,$FFE3        ; VISMAT offset -29 for ??
        ADD     HL,BC
        LD      C,E
        LD      B,$00
        ADD     HL,BC
        LD      A,D
        CALL    L81BA           ; BIT^ do "Bit in A to Mask Translation"
        AND     (HL)
        POP     BC
        POP     HL
        RET

