        RET     NZ
        LD      A,(IY+$5D)      ; OBJSV offset 93 for ( OBJect State Variable )
        CP      $01             ; HSATP constant 1 for ( HoStage Attached to Player )
        RET     NZ
        LD      A,($EEE6)       ; P-S read ( Player State ) Byte-Variable in Static RAM
        DEC     A
        CP      $02
        RET     NC              ; if ?? ( MAKE SURE PLAYER IN MAZE )
        EXX
