        LD      (IX+$5D),$03    ; OBJSV offset 93 = MSSNA for ( Monster State SNAtch hostage )
        LD      (IX+$54),$01    ; MYFLAG offset 84 = 1 for "SET ME EATEN"
        LD      H,B
