;  3 CPI,
;  Sm0 JRZ, ( RANDOM BREAK )
; ( SPIDER CHASE PLAYER ROUTINE )
;  PLYRV X LXIX,
;  BEARV CALL,
;  A E MOV,
;  0 D MVI,
;  B2DP H LXI,
;  D DAD,
;  LDAR,
;  1 ANI,
;  M A MOV,
;  0<>, IF,
