;   1 VANIMTIMER Y MVIX,
;  THEN,
;  RET,
;
; CH-PX does "CHange vectors Perspective indeX" routine
LAA47:  CP      (IY+$3A)        ; VPERINX offset 58 for "VECTORS PERspective INdeX"
        JR      Z,LAA57                 ; (+$0b) IF 0<> False RETurn
        LD      (IY+$3A),A      ; VPERINX offset 58 again
