;  A L MOV,
;  0 H MVI,
;  H PUSH,
; NEXT
; DECIMAL
;
; IJS does (TERSE-called) Input JoyStick (by COCKTAIL mode) where IY is the TersePC !!
CALL    LAB0D           ; Ijs do "Input CURRENT JoyStick port"
        LD      L,A
        LD      H,$00
        PUSH    HL
        DW	_NEXT            ; indexed RETurn

