        DW      $B3C0           ; MIS-INT point to MISsle INTerrupt test ?? routine
        ;
        DW      $00BC           ; SUI1V "pushWORD to System stack"
        DW      $FEFC           ; for Word ?? (an Interrupt Vector !!) in Static RAM
        ;
        DW      $0127           ; ! do "Pop HL, Pop DE, word DE->(HL)"
        ;
        DW      $1F34           ; INVERT-OFF do "clear COCKTAIL mode for UPRIGHTs"
        ;
        DW      $00BC           ; #PLA "pushWORD to System stack"
        DW      $E39A           ; for ( # of PLAyers-1 ) Byte-Variable in High WRITE-protected NV RAM
        ;
        DW      $0120           ; B@ do "Pop word, Push 0,(HL) byte to System stack"
        ; IF False to THEN #1
        DW      $03CD,$B454     ; ConditionalJUMP "only IF Top of System stack is Zero"
        ;
        DW      $00BC           ; plup "pushWORD to System stack"
        DW      $E399           ; for ( PLayer-1 UP ) Byte-Variable in High WRITE-protected NV RAM
        ;
        DW      $0120           ; B@ do "Pop word, Push 0,(HL) byte to System stack"
        ; _IF False to THEN #2
        DW      $03CD,$B454     ; ConditionalJUMP "only IF Top of System stack is Zero"
        ;
        DW      $00C5           ; do "pushBYTE to System stack"
        DB      $13             ; for =&(19) aka OPTIONS SW3 read
        ;
        DW      $02E3           ; INP do "Pop BC, INPort L,(C) byte, Push 0,L word"
        ;
        DW      $04F9           ; 8 "BYTE Pusher" to MASK bit 3 CABINet = COCKTAIL
        ;
        DW      $0220           ; AND do "word (SP) AND (SP+2)"
        ;
        DW      $01F0           ; 0= do "Pop HL, Push T on Zero or F on Not Zero"
        ; __IF False skip to THEN #3
        DW      $03CD,$B454     ; ConditionalJUMP "only IF Top of System stack is Zero"
        ;
        DW      $1F2D           ; INVERT-ON does "set COCKTAIL mode for P2 ONLY" !!
