;  XTHL,
;  M E MOV,
;  H INX,
;  M D MOV,
;  H INX,
;  D A MOV,
;  E ORA,
;  0=, IF,
;   PSW POP,
;   RET,
;  THEN,
;  XTHL,
;  XCHG,
;  NOWR B LXI,
;  B DAD,
;  SWPO CALL,
;  H INX,
;  D INX,
;  SWPO CALL,
;  H INX,
;  D INX,
;  SWPO CALL,
