        INC     HL
        INC     DE
        CALL    LB472           ; SWPO does "SWAP bytes (DE) and (HL)"
        INC     HL
        INC     DE
        CALL    LB472           ; SWPO does "SWAP bytes (DE) and (HL)"
        INC     DE
        LD      BC,$001D        ; OBJSV - NOWD (93 - 64) = 29 for ??
        ADD     HL,BC
        CALL    LB472           ; SWPO does "SWAP bytes (DE) and (HL)"
        INC     DE
        LD      BC,$FFED        ; DISTANCE - OBJSV (75 - 93) = -19 for ??
        ADD     HL,BC
        CALL    LB472           ; SWPO does "SWAP bytes (DE) and (HL)"
        INC     DE
        INC     HL
        CALL    LB472           ; SWPO does "SWAP bytes (DE) and (HL)"
        INC     DE
        JR      LB488                   ; (-$37) to Dmr for EACH entry in table

